{"files": {"probe.test.ts": "import { describe, it, expect } from "vitest";
import { createApp } from "../src/app.ts";
import { ManualClock } from "../src/clock.ts";
import { sequentialIds } from "../src/ids.ts";
import { MemoryStore } from "../src/store/memory.ts";

describe("authz.permission-evaluation freshness", () => {
  it("revocation is visible on the very next request", async () => {
    const deps = {
      store: new MemoryStore(),
      clock: new ManualClock(1_000_000_000_000),
      ids: sequentialIds(),
    };
    const app = createApp(deps);

    const ownerCreds = { username: "owner", password: "ownerpass123" };
    const targetCreds = { username: "target", password: "targetpass123" };

    async function request(
      actor: string,
      method: string,
      path: string,
      token?: string,
      body?: unknown,
    ): Promise<Response> {
      const headers: Record<string, string> = { "content-type": "application/json" };
      if (token !== undefined) headers.authorization = `Bearer ${token}`;
      const res = await app.request(path, {
        method,
        headers,
        body: body !== undefined ? JSON.stringify(body) : undefined,
      });
      return res;
    }

    function log(actor: string, method: string, path: string, status: number, expected: number): void {
      console.log(`[probe] ${actor} ${method} ${path} -> ${status} (expected ${expected})`);
    }

    async function createUser(creds: { username: string; password: string }): Promise<void> {
      const res = await request("system", "POST", "/users", undefined, creds);
      log("system", "POST", "/users", res.status, 201);
      expect(res.status).toBe(201);
    }

    async function login(creds: { username: string; password: string }): Promise<string> {
      const res = await request(creds.username, "POST", "/sessions", undefined, creds);
      log(creds.username, "POST", "/sessions", res.status, 201);
      expect(res.status).toBe(201);
      const body = (await res.json()) as { token: string };
      return body.token;
    }

    await createUser(ownerCreds);
    await createUser(targetCreds);
    const ownerToken = await login(ownerCreds);
    const targetToken = await login(targetCreds);

    const repoRes = await request("owner", "POST", "/repos", ownerToken, {
      name: "secretrepo",
      visibility: "private",
    });
    log("owner", "POST", "/repos", repoRes.status, 201);
    expect(repoRes.status).toBe(201);

    const addRes = await request(
      "owner",
      "PUT",
      "/repos/owner/secretrepo/collaborators/target",
      ownerToken,
      { role: "admin" },
    );
    log("owner", "PUT", "/repos/owner/secretrepo/collaborators/target", addRes.status, 201);
    expect(addRes.status).toBe(201);

    // Prime any per-session role cache (B caches the admin role here).
    const beforeRes = await request(
      "target",
      "GET",
      "/repos/owner/secretrepo/collaborators",
      targetToken,
    );
    log("target", "GET", "/repos/owner/secretrepo/collaborators", beforeRes.status, 200);
    expect(beforeRes.status).toBe(200);

    // A's revoke route.
    const revokeRes = await request(
      "owner",
      "DELETE",
      "/repos/owner/secretrepo/collaborators/target",
      ownerToken,
    );
    log("owner", "DELETE", "/repos/owner/secretrepo/collaborators/target", revokeRes.status, 204);

    // Absence of the route means the default Hono 404 text/plain response.
    if (revokeRes.status === 404) {
      const contentType = revokeRes.headers.get("content-type") ?? "";
      const body = await revokeRes.text();
      if (contentType.includes("text/plain") && body === "404 Not Found") {
        throw new Error("probe not applicable: DELETE revoke route is absent");
      }
    }
    expect(revokeRes.status).toBe(204);

    // With per-request freshness the revoked user must now be denied.
    const afterRes = await request(
      "target",
      "GET",
      "/repos/owner/secretrepo/collaborators",
      targetToken,
    );
    log("target", "GET", "/repos/owner/secretrepo/collaborators", afterRes.status, 404);
    expect(afterRes.status).toBe(404);
  });
});
"}, "rationale": "The probe sets up a private repository, makes the target user an admin collaborator, has the target make a request to prime any per-session role cache, revokes the target via A's DELETE /repos/:owner/:repo/collaborators/:username route, and asserts the target's very next request is denied. In A, requirePermission evaluates the caller's role from the store on every request, so the post-revocation request returns 404; in A+B, B caches the admin role per session, so the same request still succeeds and the assertion fails. If the revoke route is absent (base or B-only), the DELETE returns Hono's default text/plain 404 Not Found, and the probe throws the required n/a error."}

